import bpy, math
from mathutils import Vector
# fix yellow saturation
for n in ["YellowPlastic","YellowDark"]:
    m=bpy.data.materials.get(n)
    if m:
        bsdf=m.node_tree.nodes["Principled BSDF"]
        bsdf.inputs["Base Color"].default_value=(1.0,0.68,0.0,1) if n=="YellowPlastic" else (0.9,0.58,0.0,1)
        bsdf.inputs["Roughness"].default_value=0.32
for n in ["BlackPlastic","BlackMatte"]:
    m=bpy.data.materials.get(n)
    if m:
        m.node_tree.nodes["Principled BSDF"].inputs["Roughness"].default_value=0.38
# reduce lights
for o in bpy.context.scene.objects:
    if o.type=='LIGHT':
        o.data.energy*=0.45
bpy.context.scene.view_settings.exposure=-0.3
# bigger eyes
for o in bpy.context.scene.objects:
    if o.name.startswith(("EyeRim","Eyeball","Pupil","EyeRimIn")):
        o.scale=(o.scale[0]*1.28, o.scale[1]*1.15, o.scale[2]*1.28)
# thinner gap
g=bpy.data.objects.get("GapShadow")
if g: g.scale=(0.99,0.99,0.45)
# bigger tray
for nm in ["CoinTray","TrayRing","Dollar"]:
    o=bpy.data.objects.get(nm)
    if o: o.scale=(o.scale[0]*1.25, o.scale[1]*1.25, o.scale[2])
# feet forward bigger
for o in bpy.context.scene.objects:
    if o.name.startswith("Foot") and "Groove" not in o.name or o.name.startswith("Sole"):
        o.location.y-=0.18; o.scale=(o.scale[0]*1.15, o.scale[1]*1.25, o.scale[2]*1.1)
# ROBIE bolder
r=bpy.data.objects.get("ROBIE")
if r: r.data.size=0.20; r.location.x=-0.32
# ground smaller / darker bg handled later
result={"ok":True}

