import bpy, os
from mathutils import Vector
for nm in ["PupilL","PupilR"]:
    o=bpy.data.objects[nm]; o.scale=(0.65,0.9,0.55); o.location.z=1.68; o.location.y=-0.90
for nm in ["EyeballL","EyeballR"]:
    o=bpy.data.objects[nm]; o.location.y=-0.845
for nm in ["EyeRimInL","EyeRimInR"]:
    o=bpy.data.objects[nm]; o.scale=(0.82,1,0.82)
# re-render 3 views
scene=bpy.context.scene; cam=bpy.data.objects["Camera"]
def look(o,t):
    d=Vector(t)-o.location; o.rotation_euler=d.to_track_quat('-Z','Y').to_euler()
for loc,path in [((0,-5.4,2.0),'output/robbie_front.png'),((3.6,-4.4,3.2),'output/robbie_threequarter.png'),((-2.8,4.4,3.4),'output/robbie_back.png')]:
    cam.location=loc; look(cam,(0,0,1.0)); scene.render.filepath=os.path.abspath(path); bpy.ops.render.render(write_still=True)
# re-export
exclude={'Ground','Camera','Key','Fill','Rim'}
bpy.ops.object.select_all(action='DESELECT')
for o in bpy.context.scene.objects:
    if o.name not in exclude and o.type=='MESH': o.select_set(True)
out=os.path.abspath('output/robbie_banker.glb')
bpy.ops.export_scene.gltf(filepath=out, export_format='GLB', use_selection=True, export_apply=True, export_draco_mesh_compression_enable=False)
result={"size":os.path.getsize(out)}

